package local.ttlab.gallery;
import android.database.Cursor;import java.util.*;
/** Derived inventory is encrypted SQL, streamed in bounded batches instead of retaining every block in Java. */
final class StorageIndex {
 final Library library;final Vault vault;private volatile long revision;private long capturedRevision=-1,generation;
 StorageIndex(Library library,Vault vault){this.library=library;this.vault=vault;}
 void invalidate(){revision++;}
 void record(Item item,boolean thumbnail,int index){own(vault.hash((thumbnail?"thumb/":"media/")+item.cacheKey()+(thumbnail?"":"/"+index)),item.channel,thumbnail?0:1);}
 private void own(String hash,int channel,int kind){library.db.execSQL("INSERT INTO storage_owners(hash,channel,kind,updated) VALUES(?,?,?,?) ON CONFLICT(hash) DO UPDATE SET channel=excluded.channel,kind=excluded.kind,updated=excluded.updated",new Object[]{hash,channel,kind,System.currentTimeMillis()});}
 static final class Usage{long cache,saved,thumbnails,originals;}
 static final class Snapshot{long cache,saved,thumbnails,originals,unknownCache,unknownSaved;final Map<Integer,Usage> chats=new TreeMap<>();}
 private void capture()throws java.io.IOException{
  if(capturedRevision==revision&&generation==Long.parseLong(library.setting("storage-generation","0")))return;long requested=revision,start=System.currentTimeMillis();generation=Long.parseLong(library.setting("storage-generation","0"))+1;if(generation<=0)throw new java.io.IOException("Generación de inventario inválida");library.setSetting("storage-generation",Long.toString(generation));List<Vault.Entry> batch=new ArrayList<>(512);
  vault.visit(file->{batch.add(file);if(batch.size()==512){captureBatch(batch);batch.clear();}});captureBatch(batch);
  // Concurrent newly registered files must survive pruning even if this directory walk did not see them.
  library.db.execSQL("DELETE FROM storage_owners WHERE rowid IN(SELECT rowid FROM storage_owners WHERE seen<>? AND updated<? LIMIT 4096)",new Object[]{generation,start});capturedRevision=requested;
 }
 private void captureBatch(List<Vault.Entry> files){if(files.isEmpty())return;library.db.beginTransaction();try{for(Vault.Entry file:files)library.db.execSQL("INSERT INTO storage_owners(hash,channel,kind,bytes,saved,seen,updated) VALUES(?,0,0,?,?,?,0) ON CONFLICT(hash) DO UPDATE SET bytes=CASE WHEN storage_owners.seen=excluded.seen AND storage_owners.saved>excluded.saved THEN storage_owners.bytes ELSE excluded.bytes END,saved=CASE WHEN storage_owners.seen=excluded.seen THEN MAX(storage_owners.saved,excluded.saved) ELSE excluded.saved END,seen=excluded.seen",new Object[]{file.hash,file.bytes,file.saved?1:0,generation});library.db.setTransactionSuccessful();}finally{library.db.endTransaction();}}
 Snapshot snapshot()throws java.io.IOException{synchronized(library){capture();Snapshot out=new Snapshot();try(Cursor c=library.db.rawQuery("SELECT channel,COALESCE(sum(CASE WHEN saved=0 THEN bytes ELSE 0 END),0),COALESCE(sum(CASE WHEN saved=1 THEN bytes ELSE 0 END),0),COALESCE(sum(CASE WHEN kind=0 THEN bytes ELSE 0 END),0),COALESCE(sum(CASE WHEN kind=1 THEN bytes ELSE 0 END),0) FROM storage_owners WHERE seen=? GROUP BY channel",new String[]{""+generation})){while(c.moveToNext()){int channel=c.getInt(0);long cache=c.getLong(1),saved=c.getLong(2);out.cache+=cache;out.saved+=saved;if(channel==0){out.unknownCache+=cache;out.unknownSaved+=saved;continue;}Usage chat=new Usage();chat.cache=cache;chat.saved=saved;chat.thumbnails=c.getLong(3);chat.originals=c.getLong(4);out.thumbnails+=chat.thumbnails;out.originals+=chat.originals;out.chats.put(channel,chat);}}return out;}}
 boolean scan(int budget)throws java.io.IOException{synchronized(library){
  if(budget<1||budget>4096)throw new IllegalArgumentException();capture();String position=library.setting("storage-scan","0:-1");if(position.equals("done")||!unknown())return true;String[] parts=position.split(":");long row=Long.parseLong(parts[0]);int index=Integer.parseInt(parts[1]);Map<String,int[]> batch=new LinkedHashMap<>();boolean finished=false;
  library.db.beginTransaction();try{while(budget>0){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException();Item item;long actual;int chunks;boolean full;try(Cursor c=library.db.rawQuery("SELECT "+Library.COLUMNS+",rowid,offline,COALESCE((SELECT progress FROM downloads d WHERE d.channel=media.channel AND d.id=media.id AND d.revision=media.revision),0) FROM media WHERE rowid>=? ORDER BY rowid LIMIT 1",new String[]{""+row})){if(!c.moveToFirst()){finished=true;break;}item=Item.cursor(c);actual=c.getLong(11);long prefix=c.getLong(13);full=c.getInt(12)!=0||prefix>0;chunks=c.getInt(12)!=0?item.chunks():prefix>0?(int)Math.min(item.chunks(),(prefix+Source.CHUNK-1)/Source.CHUNK):Math.min(20,item.chunks());}if(actual!=row)index=-1;row=actual;
    // shortcut: pre-2.7 remote cache scans header/tail candidates; expand migration if exact historical attribution becomes necessary.
    while(budget>0&&index<chunks){int part=full||item.chunks()<=20||index<16?index:item.chunks()-4+index-16;String hash=vault.hash((index<0?"thumb/":"media/")+item.cacheKey()+(index<0?"":"/"+part));batch.put(hash,new int[]{item.channel,index<0?0:1});index++;budget--;if(batch.size()==128){associate(batch);batch.clear();}}if(index>=chunks){row++;index=-1;}}
   associate(batch);library.setSetting("storage-scan",finished?"done":row+":"+index);library.db.setTransactionSuccessful();return finished||!unknown();}finally{library.db.endTransaction();}
 }}
 private boolean unknown(){try(Cursor c=library.db.rawQuery("SELECT 1 FROM storage_owners WHERE seen=? AND channel=0 LIMIT 1",new String[]{""+generation})){return c.moveToFirst();}}
 private void associate(Map<String,int[]> candidates){if(candidates.isEmpty())return;List<String> found=new ArrayList<>();String sql="SELECT hash FROM storage_owners WHERE channel=0 AND seen=? AND hash IN("+String.join(",",Collections.nCopies(candidates.size(),"?"))+")";List<String> args=new ArrayList<>();args.add(""+generation);args.addAll(candidates.keySet());try(Cursor c=library.db.rawQuery(sql,args.toArray(new String[0]))){while(c.moveToNext())found.add(c.getString(0));}for(String hash:found){int[] owner=candidates.get(hash);own(hash,owner[0],owner[1]);}}
 void clearChatCache(int channel)throws Exception{synchronized(library){capture();long last=0;while(true){List<String> hashes=new ArrayList<>(128);try(Cursor c=library.db.rawQuery("SELECT rowid,hash FROM storage_owners WHERE seen=? AND channel=? AND saved=0 AND rowid>? ORDER BY rowid LIMIT 128",new String[]{""+generation,""+channel,""+last})){while(c.moveToNext()){last=c.getLong(0);hashes.add(c.getString(1));}}if(hashes.isEmpty())break;vault.removeCached(hashes);}invalidate();}}
}
